  "“跟随系统”遵循手机的自动旋转设置；选择横屏或竖屏可固定本应用的方向。": "‘시스템 따르기’는 휴대폰의 자동 회전 설정을 따릅니다. 가로 또는 세로를 선택하면 이 앱의 화면 방향이 고정됩니다.",
