  "无需启动 Harness 也能管理插件。每个条目对应一个插件包，展开后可以调整其中的子插件。": "Harness를 시작하지 않아도 플러그인을 관리할 수 있습니다. 각 항목은 플러그인 패키지이며, 펼치면 하위 플러그인을 조정할 수 있습니다.",
