  "官方组件和安全组件会保留，第三方插件只会被停用，不会删除插件或数据。之后可以在列表中逐个重新启用。": "공식 구성 요소와 보안 구성 요소는 유지됩니다. 서드파티 플러그인은 비활성화될 뿐 플러그인이나 데이터는 삭제되지 않으며, 나중에 목록에서 하나씩 다시 활성화할 수 있습니다.",
  "禁用": "비활성화",
