  "{0} 个文件 · {1}": "{0}개 파일 · {1}",
  "最近记录": "최근 기록",
  "诊断日志只包含应用内部的事件名、状态码、布尔值与计数；导出文件头另有应用版本、Android SDK、ABI、Android 版本与安全补丁级别，以及机型与 ROM 的匿名摘要（稳定哈希，不含原始型号或构建串；不含序列号、IMEI、Android ID、账号）。不含 URL、模型密钥、Harness 临时密码、设备桥令牌、终端内容或文件路径。日志保存在应用私有目录且不参与备份，到期自动删除。": "진단 로그에는 앱 내부의 이벤트명, 상태 코드, 불리언 값, 카운트만 들어갑니다. 내보내기 파일 헤더에는 앱 버전, Android SDK, ABI, Android 버전, 보안 패치 수준과 기종 및 ROM의 익명 요약(안정 해시로, 원본 모델명이나 빌드 문자열, 시리얼 번호, IMEI, Android ID, 계정은 포함되지 않음)이 추가됩니다. URL, 모델 키, Harness 임시 비밀번호, 기기 브리지 토큰, 터미널 내용, 파일 경로는 포함되지 않습니다. 로그는 앱 전용 디렉터리에 저장되고 백업에 포함되지 않으며, 만료되면 자동 삭제됩니다.",
  "导出并分享": "내보내기 및 공유",
  "用系统浏览器打开 Harness": "시스템 브라우저로 Harness 열기",
  "已在系统浏览器中打开": "시스템 브라우저에서 열림",
  "打开方式": "열기 방식",
  "每次询问（系统选择器）": "매번 묻기 (시스템 선택기)",
  "系统浏览器列表已更新": "시스템 브라우저 목록이 갱신되었습니다",
  "固定一个浏览器后，点上面的按钮就用它直接打开；选「每次询问」则每次都交给系统选择器。浏览器卸载后会自动回到每次询问。": "브라우저를 고정하면 위 버튼을 누르면 그걸로 바로 열립니다.「매번 묻기」를 선택하면 매번 시스템 선택기에 맡깁니다. 브라우저를 삭제하면 자동으로 매번 묻기로 돌아갑니다.",
  "系统浏览器拿到的是与本次运行绑定的令牌，可以完整使用 Harness（不是只读预览）。运行环境停止后令牌失效；重新打开时请回到应用再次点击。": "시스템 브라우저가 받는 것은 이번 실행에 묶인 토큰이라 Harness를 완전히 사용할 수 있습니다(읽기 전용 미리보기가 아님). 실행 환경이 멈추면 토큰이 무효화됩니다. 다시 열 때는 앱으로 돌아가 다시 누르세요.",
  "使用系统浏览器仅用于诊断：令牌放在地址片段里、每次启动最多用 3 次，浏览器会话 10 分钟后失效，届时回到应用重新点击即可。": "시스템 브라우저는 진단용으로만 사용합니다. 토큰은 주소 프래그먼트에 담기며 실행할 때마다 최대 3번까지 쓸 수 있고, 브라우저 세션은 10분 후 만료됩니다. 만료되면 앱으로 돌아와 다시 누르기만 하면 됩니다.",
  "清空日志": "로그 비우기",
  "诊断日志已清空": "진단 로그가 비워졌습니다",
