  "导出诊断日志失败，请重试。": "진단 로그 내보내기에 실패했습니다. 다시 시도하세요.",
  "诊断日志状态格式无效": "진단 로그 상태 형식이 잘못되었습니다",
  "诊断日志保留天数必须是 1 到 30 之间的整数": "진단 로그 보관 일수는 1에서 30 사이의 정수여야 합니다.",
