  "状态更新时间格式无效": "상태 갱신 시간 형식이 잘못되었습니다",
  "投递区": "전달 영역",
  "inbox / outbox 与访客之间的批量搬运；不会自动搬运，必须点下面的按钮。": "inbox / outbox와 게스트 사이의 일괄 이동이며 자동으로 옮겨지지 않고 아래 버튼을 눌러야 합니다.",
  "用户放入（inbox）": "사용자가 넣음 (inbox)",
  "产物取出（outbox）": "결과 꺼냄 (outbox)",
  "访客内挂载点": "게스트 내 마운트 지점",
  "inbox 内文件": "inbox 내 파일",
  "{0} 个": "{0}개",
  "可导入的 tar：": "가져올 수 있는 tar: ",
  "搬运不可用": "이동 사용 불가",
  "导入到工作区": "워크스페이스로 가져오기",
  "导出工作区": "워크스페이스 내보내기",
  "去开启「所有文件访问」": "「모든 파일 접근」켜러 가기",
  "重新检查": "다시 확인",
  "导入落点是工作区内的 {0}/ 子目录；导出固定产出 {1} + {2} + {3}（含逐条 sha256）。": "가져오기 대상은 워크스페이스 안의 {0}/ 하위 디렉터리입니다. 내보내기는 항상 {1} + {2} + {3}(항목별 sha256 포함)을 만듭니다.",
  "存储权限：媒体读取（T1）{0} · 所有文件访问（T2）{1}。外部工作区需要 T2。": "저장 권한: 미디어 읽기 (T1) {0} · 모든 파일 접근 (T2) {1}. 외부 워크스페이스는 T2가 필요합니다.",
  "inbox / outbox 不是工作区：dsh 的 write 工具写 /mnt/inbox、/mnt/outbox 会失败（实测 EACCES），这是预期行为；搬运只能走这里的按钮。": "inbox / outbox는 워크스페이스가 아닙니다. dsh의 write 도구가 /mnt/inbox, /mnt/outbox에 쓰면 실패합니다(실측 EACCES). 이는 예상된 동작이며 이동은 여기 버튼으로만 합니다.",
  "最近一次导入：{0} 个条目 · {1} · manifest {2}": "최근 가져오기: {0} 항목 · {1} · manifest {2}",
  "最近一次导出：{0} 个条目 · {1} · manifest {2}": "최근 내보내기: {0} 항목 · {1} · manifest {2}",
  "未附带": "첨부 안 됨",
  "无法读取搬运状态，请重试": "이동 상태를 읽지 못했습니다. 다시 시도하세요.",
  "正在读取搬运状态": "이동 상태 읽는 중",
  "未读取": "읽지 않음",
  "需要授权": "권한 필요",
  "不支持": "미지원",
  "不可写": "쓰기 불가",
  "尚未授予「所有文件访问」。请到系统设置里为 DSH 手动开启；开启后回到本页会重新检查。没有该权限时只能用终端或控制台上传文件。": "「모든 파일 접근」이 아직 부여되지 않았습니다. 시스템 설정에서 DSH에 직접 켜세요. 켜면 이 페이지로 돌아왔을 때 다시 확인합니다. 이 권한이 없으면 터미널이나 콘솔로만 파일을 올릴 수 있습니다.",
  "当前系统不存在「所有文件访问」这一档，投递区无法启用；请改用终端或控制台上传文件。Harness 本身不受影响。": "이 시스템에는「모든 파일 접근」단계가 없어 전달 영역을 켤 수 없습니다. 터미널이나 콘솔로 파일을 올리세요. Harness 자체는 영향을 받지 않습니다.",
  "已授予「所有文件访问」，但投递区目录仍不可读写；可能是系统限制或目录被占用。工作区与 Harness 不受影响。": "「모든 파일 접근」이 부여되었지만 전달 영역 디렉터리가 여전히 읽고 쓸 수 없습니다. 시스템 제한이나 디렉터리 점유일 수 있습니다. 워크스페이스와 Harness는 영향을 받지 않습니다.",
  "投递区已导入工作区": "전달 영역이 워크스페이스로 가져와졌습니다",
  "投递区文件夹已创建": "전달 영역 폴더가 만들어졌습니다",
  "文件夹管理": "폴더 관리",
  "新建文件夹": "새 폴더",
  "请输入新文件夹名称（仅支持单层名称）": "새 폴더 이름을 입력하세요 (단일 계층 이름만 지원)",
  "文件夹已创建": "폴더 만들어짐",
  "当前目录": "현재 디렉터리",
  "当前目录为空": "현재 디렉터리 비어 있음",
  "当前目录条目较多，仅显示前 {0} 项；请进入子目录继续浏览。": "현재 디렉터리 항목이 많아 앞의 {0}개만 보입니다. 하위 디렉터리로 들어가 계속 보세요.",
  "无法读取当前搬运目录，请重试": "현재 이동 디렉터리를 읽지 못했습니다. 다시 시도하세요.",
  "无法读取当前目录，请重试": "현재 디렉터리를 읽지 못했습니다. 다시 시도하세요.",
  "导出到当前目录": "현재 디렉터리로 내보내기",
  "当前导出目标：outbox/{0}": "현재 내보내기 대상: outbox/{0}",
  "inbox · 用户放入": "inbox · 사용자가 넣음",
  "outbox · 产物取出": "outbox · 결과 꺼냄",
  "外部工作区：一处浏览、建文件夹与搬运": "외부 워크스페이스: 한 곳에서 찾아보기, 폴더 만들기, 이동하기",
  "选择要浏览的目录": "찾아볼 디렉터리 선택",
  "这里的目录都是访客能看到的「外部工作区」：手机上的文件夹挂进访客的 /mnt/user/<序号>，可以直接读写；inbox / outbox 是批量搬运通道，只能靠按钮搬运。": "여기 디렉터리는 모두 게스트가 보는「외부 워크스페이스」입니다. 폰의 폴더가 게스트의 /mnt/user/<번호>로 마운트되어 바로 읽고 쓸 수 있습니다. inbox / outbox는 일괄 이동 통로라 버튼으로만 옮깁니다.",
  "选一个目录浏览它的子目录；导入到工作区与导出工作区只对 inbox / outbox 有效。": "디렉터리 하나를 골라 하위 디렉터리를 보세요. 워크스페이스로 가져오기와 워크스페이스 내보내기는 inbox / outbox에만 적용됩니다.",
  "还没有挂进来的目录：在下面「目录」里添加一个手机上的目录，它会出现在这里。": "아직 마운트된 디렉터리가 없습니다. 아래「디렉터리」에서 폰의 디렉터리를 추가하면 여기에 나타납니다.",
  "挂进来的目录是实时挂载：进去之后可以直接读写，inbox / outbox 才需要先搬运一次。": "마운트된 디렉터리는 실시간 마운트입니다. 들어가면 바로 읽고 쓸 수 있고, inbox / outbox만 먼저 한 번 옮겨야 합니다.",
  "投递区已导出到 outbox": "전달 영역이 outbox로 내보내졌습니다",
  "浏览器预览不支持导入投递区": "브라우저 미리보기는 전달 영역 가져오기를 지원하지 않습니다",
  "浏览器预览不支持导出投递区": "브라우저 미리보기는 전달 영역 내보내기를 지원하지 않습니다",
