  "投递区导出起点格式无效": "전달 영역 내보내기 시작점 형식이 잘못되었습니다",
  "投递区跳过链接数格式无效": "전달 영역 건너뛴 링크 수 형식이 잘못되었습니다.",
  "投递区跳过特殊条目数格式无效": "전달 영역 건너뛴 특수 항목 수 형식이 잘못되었습니다.",
