  "所有文件访问支持状态格式无效": "모든 파일 접근 지원 상태 형식이 잘못되었습니다.",
  "媒体权限结果格式无效": "미디어 권한 결과 형식이 잘못되었습니다.",
  "所有文件访问结果格式无效": "모든 파일 접근 결과 형식이 잘못되었습니다.",
