  "已紧急停止自动化": "자동화를 긴급 중지했습니다",
  "自动化只能在这里开启。总开关不是「运行中」时，规则动作会被拒绝。暂停或紧急停止不会关闭系统无障碍服务，也不会清空白名单和规则。": "자동화는 여기서만 켤 수 있습니다. 마스터 스위치가 '실행 중'이 아니면 규칙 동작은 거부됩니다. 일시 중지나 긴급 중지는 시스템 접근성 서비스를 끄지 않으며 허용 목록과 규칙도 지우지 않습니다.",
  "无障碍服务已连接": "접근성 서비스 연결됨",
  "系统已开启，但服务未连接": "시스템에서는 켜져 있지만 서비스가 연결되지 않았습니다",
  "系统未开启": "시스템에서 꺼져 있음",
  "：服务已运行；只有总开关显示「运行中」时，规则动作才会执行。": ": 서비스가 실행 중입니다. 마스터 스위치가 '실행 중'일 때만 규칙 동작이 실행됩니다.",
  "：请在系统无障碍设置中手动开启（必要时先关闭再开启一次），应用无法代为开启。": ": 시스템 접근성 설정에서 직접 켜세요(필요하면 껐다가 다시 켜 보세요). 앱이 대신 켤 수는 없습니다.",
  "本次会话的运行记录": "이번 세션의 실행 기록",
  "只保留无障碍服务本次运行期间的数据": "접근성 서비스가 이번에 실행되는 동안의 데이터만 보관합니다",
  "记录只在无障碍服务本次运行期间存在，服务被系统回收后会从空开始——这里为空不代表没有发生过动作。记录里只有受控码与规则标识，不含界面文字、不含截图。": "기록은 접근성 서비스가 이번에 실행되는 동안에만 존재하며, 서비스가 시스템에서 회수되면 빈 목록으로 시작됩니다. 여기가 비어 있다고 해서 동작이 없었던 것은 아닙니다. 기록에는 통제 코드와 규칙 식별자만 있고 화면 텍스트나 스크린샷은 없습니다.",
  "运行记录读取失败，请稍后重试": "실행 기록을 읽지 못했습니다. 잠시 후 다시 시도하세요.",
