  "无障碍服务当前未连接，无法读取运行记录。": "접근성 서비스가 연결되어 있지 않아 실행 기록을 읽을 수 없습니다.",
  "服务已连接，还没有运行记录。": "서비스는 연결되었지만 실행 기록이 아직 없습니다.",
  "更早的 {0} 条记录已超出容量被丢弃。": "이전 기록 {0}개가 용량을 초과해 삭제되었습니다.",
