  "规则由 AI 生成，保存前需要你确认；这里只能启用或停用规则，不能修改内容。停用规则不会删除它。": "규칙은 AI가 생성하며, 저장 전에 확인이 필요합니다. 여기서는 규칙을 켜거나 끌 수만 있고 내용은 수정할 수 없습니다. 규칙을 꺼도 삭제되지는 않습니다.",
  "白名单里还没有其他应用：先在上面加入目标应用，规则才有归属。": "허용 목록에 다른 앱이 아직 없습니다. 위에서 대상 앱을 먼저 추가해야 규칙을 연결할 수 있습니다.",
