  "没有读回这条规则的内容，编辑器不会打开：直接保存会覆盖掉原有选择器。": "이 규칙의 내용을 다시 읽어오지 못해 편집기를 열지 않습니다. 지금 저장하면 기존 선택자가 덮어써집니다.",
  "所属应用：{0}（固定，不可在表单里改）": "소속 앱: {0}(고정, 이 양식에서 변경할 수 없음)",
  "保存时会整条替换这条规则，表单里带着读回的全部字段。": "저장하면 이 규칙이 통째로 교체되며, 양식에는 다시 읽어온 모든 필드가 담깁니다.",
