  "参数读取失败，请稍后重试": "매개변수를 읽지 못했습니다. 잠시 후 다시 시도하세요.",
  "读取参数完成前不会显示输入框，也不会用默认值代替；否则保存时可能把未经确认的默认值写入设备。": "매개변수를 다 읽기 전에는 입력란을 표시하지 않고 기본값으로 대신하지도 않습니다. 확인하지 않은 기본값이 기기에 저장되는 일을 막기 위해서입니다.",
  "参数内容不合法": "매개변수 내용이 올바르지 않습니다",
  "这份参数已经读不出来：{0}（受控码 {1}）。原生按「已暂停」处理，也不会自动删掉它；保存一次就会覆盖掉它。": "이 매개변수는 더 이상 읽을 수 없습니다: {0}(코드 {1}). 네이티브는 이를 '일시 중지됨'으로 처리하며 자동으로 삭제하지도 않습니다. 한 번 저장하면 덮어써집니다.",
  "{0} 不在白名单里：保存参数会被原生拒绝。": "허용 목록에 없는 앱입니다: {0}. 매개변수를 저장하면 네이티브에서 거부됩니다.",
  "当前生效：{0} · 默认动作上限 {1} · 默认冷却时间 {2} 毫秒 · 默认匹配延迟 {3} 毫秒": "현재 적용: {0} · 기본 동작 횟수 상한 {1} · 기본 쿨다운 시간 {2}밀리초 · 기본 일치 지연 {3}밀리초",
  "该应用已暂停": "이 앱은 일시 중지되었습니다",
  "该应用未暂停": "이 앱은 일시 중지되지 않았습니다",
  "这三个默认值只用于新建规则表单的初值，不会改动任何一条已有规则。": "이 세 기본값은 새 규칙 양식의 초깃값으로만 쓰이며, 기존 규칙은 하나도 바뀌지 않습니다.",
  "暂停这个应用的自动化": "이 앱의 자동화 일시 중지",
  "只挡规则自动求值：设备桥的单次动作（AI 明确要求的那一下）照旧走白名单与敏感窗口判定；暂停期间被丢掉的事件会计入运行记录里的「拦截原因」。": "규칙 자동 평가만 막습니다. 기기 브리지를 통한 단일 동작(AI가 명시적으로 요청한 동작)은 그대로 허용 목록과 민감한 화면 판정을 거칩니다. 일시 중지 동안 버려진 이벤트는 실행 기록의 '차단 사유'에 집계됩니다.",
